L(OA14, 4,
  mat="Papel cuadriculado y lápiz. Dibuja las baldosas con regla si puedes.",
  use="Aprenderé a diseñar y comprobar teselados combinando traslaciones, reflexiones y rotaciones. Sirve para decidir cuántas baldosas hacen falta y si un diseño cubre sin huecos.",
  prior=["Sé que los ángulos en un vértice deben sumar 360°.", "Sé trasladar, reflejar y girar figuras."],
  explain=[
      "Para armar un teselado primero se elige una figura y luego se repite con traslaciones, reflexiones o rotaciones. Después se comprueba que no haya huecos ni montajes: alrededor de cada vértice los ángulos suman 360°.",
      "Algunas figuras no son regulares, pero igual teselan. Un triángulo rectángulo con catetos 3 y 4 se gira 180° y, junto a la copia original, forma un rectángulo de 3 por 4. Ese rectángulo se repite por traslación y cubre todo el plano.",
      "Para saber cuántas baldosas cubren una región, se divide el área de la región por el área de una baldosa. El patio de 12 por 8 tiene 96 unidades cuadradas y cada triángulo de catetos 3 y 4 mide (3 × 4) ÷ 2 = 6, así que se necesitan 16 baldosas.",
  ],
  vocab=[("patrón", "diseño que se repite de manera ordenada"), ("baldosa", "pieza que se repite para cubrir una superficie"), ("área de la región", "cantidad de superficie que debe cubrirse"), ("comprobar", "verificar que el diseño cumple las condiciones")],
  worked=[
      ("Contar baldosas triangulares", "Un patio rectangular de 12 m por 8 m se cubre con baldosas que son triángulos rectángulos de catetos 3 m y 4 m. ¿Cuántas baldosas se necesitan?", ["El patio tiene 12 × 8 = 96 m² y cada baldosa 3 × 4 ÷ 2 = 6 m².", "96 ÷ 6 = 16 baldosas."], "16 baldosas"),
      ("Revisar un diseño", "Un diseño junta 2 hexágonos regulares (120° cada uno) y 1 cuadrado (90°) en un vértice. ¿Teselan sin huecos ni montajes?", ["Los ángulos suman 120 + 120 + 90 = 330°.", "Faltan 30°, así que queda un hueco."], "No: queda un hueco de 30°"),
  ],
  mist=[
      ("Dividir el largo del patio por el largo de una baldosa sin pensar en el área.", "Una baldosa triangular no cubre un rectángulo entero: dos triángulos recién forman uno, y el largo solo no dice cuántas caben.", "Compara áreas: patio ÷ baldosa."),
      ("Dar por buena una unión que suma 350° en un vértice.", "Con 350° queda un hueco de 10°.", "El vértice debe sumar exactamente 360°."),
  ],
  R=[arith("Un triángulo rectángulo tiene catetos 5 cm y 4 cm. Calcula su área.", "5*4//2", "El área de un triángulo es base × altura ÷ 2.", " cm²"),
     ex("Dos triángulos rectángulos iguales, unidos por la hipotenusa, forman un rectángulo. ¿Qué parte del rectángulo ocupa cada triángulo?", "La mitad", "Cada triángulo ocupa la mitad del rectángulo."),
     arith("Una baldosa cuadrada tiene 20 cm de lado. ¿Cuántos cm² tiene?", "20*20", "El área de un cuadrado es lado × lado.", " cm²")],
  C=[arith("Un patio de 10 m por 6 m se cubre con baldosas rectangulares de 2 m por 1 m. ¿Cuántas baldosas se necesitan?", "10*6//(2*1)", "El área del patio es 60 m² y cada baldosa mide 2 m².", " baldosas"),
     ex("Un vértice reúne 4 triángulos equiláteros de 60° y 1 cuadrado de 90°. ¿Cuántos grados suman?", "330", "Los triángulos suman 240° y el cuadrado 90°.", calc="4*60+90"),
     ex("Un vértice reúne 2 cuadrados de 90° y 3 triángulos equiláteros de 60°. ¿Hay teselado sin huecos ni montajes? Responde sí o no.", "Sí", "Suman 180° + 180° = 360°.")],
  A=[arith("Un muro de 9 m por 4 m se cubre con baldosas que son triángulos rectángulos de catetos 3 m y 2 m. ¿Cuántas baldosas se necesitan?", "9*4//(3*2//2)", "El muro tiene 36 m² y cada baldosa 3 m².", " baldosas"),
     arith("Un patio de 15 m por 6 m se cubre con baldosas cuadradas de 3 m de lado. ¿Cuántas baldosas se necesitan?", "15*6//(3*3)", "El patio tiene 90 m² y cada baldosa 9 m².", " baldosas"),
     ex("Un vértice reúne 1 hexágono regular (120°), 1 cuadrado (90°) y 2 triángulos equiláteros (60°). ¿Cuántos grados suman?", "330", "120 + 90 + 120 = 330°, y faltan 30°.", calc="120+90+2*60")],
  Z=[ex("Lucas dice que 3 cuadrados y 1 triángulo equilátero juntos en un vértice forman un teselado. ¿Tiene razón? Responde sí o no.", "No", "Suman 270° + 60° = 330°, no 360°."),
     ex("Sofía dice que un triángulo cualquiera no puede teselar. Si el triángulo es rectángulo con catetos 3 y 4, ¿tiene razón? Responde sí o no.", "No", "Con una copia girada 180° forma un rectángulo que se repite sin huecos.")],
  D=[arith("Un piso de 24 m por 18 m se cubre en parte con 45 baldosas de 6 m² cada una. ¿Cuántos m² faltan por cubrir?", "24*18-45*6", "El piso tiene 432 m² y las baldosas cubren 270 m².", " m²"),
     ex("Un teselado usa triángulos rectángulos de catetos 6 y 8. ¿Cuántos triángulos se necesitan para cubrir un rectángulo de 24 por 24?", "24", "El rectángulo tiene 576 y cada triángulo 24 de área: 576 ÷ 24 = 24.", calc="24*24//(6*8//2)")],
  ctx=[arith("Un taller cubre un piso de 20 m por 10 m con baldosas que son triángulos rectángulos de catetos 5 m y 4 m. ¿Cuántas baldosas necesita?", "20*10//(5*4//2)", "El piso tiene 200 m² y cada baldosa 10 m².", " baldosas")],
  chk=[ex("¿Cuánto deben sumar los ángulos en un vértice de un teselado?", "360°", "Una vuelta completa mide 360°."),
       arith("Un triángulo rectángulo tiene catetos 6 cm y 8 cm. ¿Cuál es su área?", "6*8//2", "El área es base × altura ÷ 2.", " cm²"),
       ex("¿Qué se hace con el área del patio y la de la baldosa para saber cuántas baldosas se necesitan?", "Se divide el área del patio por la de la baldosa", "Cada baldosa cubre su área, así que la división da cuántas caben.")],
  open=("Elige un caso: A) cubrir un patio de 12 m por 6 m con baldosas que son triángulos rectángulos de catetos 3 m y 4 m; o B) cubrir un patio de 8 m por 6 m con baldosas rectangulares de 2 m por 1 m. Dibuja un croquis, calcula cuántas baldosas se necesitan y explica cómo se repiten (traslación, reflexión o rotación).",
        "A) El patio tiene 72 m² y cada triángulo 6 m²: 72 ÷ 6 = 12 baldosas. Cada par de triángulos, uno girado 180°, forma un rectángulo de 3 por 4 que se traslada.",
        ["croquis del patio", "cálculo de áreas", "división para contar baldosas", "nombra el movimiento usado"],
        ["croquis", "cálculos", "explicación del movimiento"],
        ["comparar largos en vez de áreas", "olvidar dividir por 2 en el triángulo", "no nombrar el movimiento"],
        "Pide que explique cómo comprueba que no hay huecos. Reconoce la comparación de áreas."),
  reinforce="Calcula cuántas baldosas cuadradas de 1 m por 1 m cubren un patio de 7 m por 5 m, y cuántas baldosas rectangulares de 7 m por 1 m. Compara los resultados.",
  extend="Diseña con palabras un teselado que combine una traslación y una reflexión de un rectángulo.")
